/* AIVIC_FUNCTION_BUNDLE_START owner=identifyWeeklyBottlenecks exports=identifyWeeklyBottlenecks */
const __aivicBundle_5_identifyWeeklyBottlenecks = (() => {
  interface WeeklyIssueDataset {
    weekStartDate: Date;
    weekEndDate: Date;
    issues: Array<{
      issueId: string;
      occurrenceDate: Date;
      impactScore: number;
      resolutionStatus: 'resolved' | 'unresolved' | 'in_progress';
    }>;
    teamId: string;
    userId?: string;
  }
  
  interface IdentifyWeeklyBottlenecksResult {
    bottlenecks: Array<{
      issueId: string;
      occurrenceFrequency: number;
      averageImpactScore: number;
      severityRank: 'critical' | 'high' | 'medium' | 'low';
    }>;
    analysisTimestamp: Date;
    weekCoverage: {
      startDate: Date;
      endDate: Date;
    };
  }
  
  class InsufficientWeeklyDataError extends Error {
    constructor(message: string) {
      super(message);
      this.name = 'InsufficientWeeklyDataError';
    }
  }
  
   function identifyWeeklyBottlenecks(input: WeeklyIssueDataset): IdentifyWeeklyBottlenecksResult {
    const permissionRequest = {
      userId: input.userId || 'system',
      resourceType: 'analysis_report' as const,
      operation: 'view' as const,
      targetTeamId: input.teamId,
      confidentialityLevel: 'internal' as const,
    };
  
    const permissionResult = judgeAccessPermission(permissionRequest);
    if (!permissionResult.isPermitted) {
      throw new Error(`Access denied: ${permissionResult.denialReason || 'Insufficient permissions'}`);
    }
  
    if (!input.issues || input.issues.length === 0) {
      throw new InsufficientWeeklyDataError('No issues found for the specified week');
    }
  
    const issueAggregation = new Map<string, { frequencies: number; impactScores: number[] }>();
  
    for (const issue of input.issues) {
      const issueDate = new Date(issue.occurrenceDate);
      if (issueDate >= input.weekStartDate && issueDate <= input.weekEndDate) {
        const existing = issueAggregation.get(issue.issueId) || { frequencies: 0, impactScores: [] };
        existing.frequencies += 1;
        existing.impactScores.push(issue.impactScore);
        issueAggregation.set(issue.issueId, existing);
      }
    }
  
    if (issueAggregation.size === 0) {
      throw new InsufficientWeeklyDataError('No issues found within the specified week period');
    }
  
    const bottlenecks: Array<{
      issueId: string;
      occurrenceFrequency: number;
      averageImpactScore: number;
      severityRank: 'critical' | 'high' | 'medium' | 'low';
    }> = [];
  
    for (const [issueId, data] of issueAggregation.entries()) {
      const averageImpactScore = data.impactScores.reduce((sum, score) => sum + score, 0) / data.impactScores.length;
  
      let severityRank: 'critical' | 'high' | 'medium' | 'low';
      if (averageImpactScore >= 80 && data.frequencies >= 3) {
        severityRank = 'critical';
      } else if (averageImpactScore >= 70 || data.frequencies >= 3) {
        severityRank = 'high';
      } else if (averageImpactScore >= 50 || data.frequencies >= 2) {
        severityRank = 'medium';
      } else {
        severityRank = 'low';
      }
  
      bottlenecks.push({
        issueId,
        occurrenceFrequency: data.frequencies,
        averageImpactScore: Math.round(averageImpactScore * 100) / 100,
        severityRank,
      });
    }
  
    bottlenecks.sort((a, b) => {
      const severityOrder = { critical: 0, high: 1, medium: 2, low: 3 };
      const severityDiff = severityOrder[a.severityRank] - severityOrder[b.severityRank];
      if (severityDiff !== 0) return severityDiff;
      return b.averageImpactScore - a.averageImpactScore;
    });
  
    return {
      bottlenecks,
      analysisTimestamp: new Date(),
      weekCoverage: {
        startDate: new Date(input.weekStartDate),
        endDate: new Date(input.weekEndDate),
      },
    };
  }
  return { identifyWeeklyBottlenecks };
})();
export const identifyWeeklyBottlenecks = __aivicBundle_5_identifyWeeklyBottlenecks.identifyWeeklyBottlenecks;
/* AIVIC_FUNCTION_BUNDLE_END owner=identifyWeeklyBottlenecks */

